// 200-question CLF-C02 pool (auto-generated; do not edit by hand)
const POOL = [{"id": 1, "domain": 1, "q": "A company's books show millions spent buying servers that sat mostly idle between seasonal peaks. Moving to AWS, which advantage of cloud computing addresses this directly?", "choices": ["Converting variable operating spend into fixed multi-year commitments", "Amortizing the same server purchases across a longer fiscal horizon", "Trading capital expense for variable expense — paying only for resources actually used", "Renting idle in-house capacity out to other companies"], "answer": 2, "why": "Correct: Trading capital expense for variable expense — paying only for resources actually used"}, {"id": 2, "domain": 1, "q": "Per-unit prices on AWS are consistently lower than a single company could achieve with its own hardware pool. Which mechanism produces this pricing?", "choices": ["Usage aggregated across hundreds of thousands of customers", "Volume discounts AWS grants only to enterprise support customers", "Uniquely low electricity costs in AWS data-center locations", "Price cuts that apply only after a multi-year contract is signed"], "answer": 0, "why": "Correct: Usage aggregated across hundreds of thousands of customers"}, {"id": 3, "domain": 1, "q": "A product team in Singapore prepares a launch for users across Asia, Europe, and the Americas. Which advantage does standing up infrastructure in three Regions with a few clicks illustrate?", "choices": ["Trading fixed expense for variable expense", "Faster construction of company-owned server rooms", "Scale economies on networking hardware", "Go global in minutes"], "answer": 3, "why": "Correct: Go global in minutes"}, {"id": 4, "domain": 1, "q": "After a migration, the infrastructure team stops planning server-room capacity and instead ships product features. Which benefit of cloud computing is at work?", "choices": ["Guaranteed five-nines availability in every Region", "No spending on running and maintaining data centers", "Automatic compliance certification for all workloads", "Free hardware refreshes bundled with every service"], "answer": 1, "why": "Correct: No spending on running and maintaining data centers"}, {"id": 5, "domain": 1, "q": "A team wants to test five proof-of-concept architectures this month and shut the failing ones down within days. Which benefit makes that practical?", "choices": ["Change requests are pre-approved by an AWS review board", "Experiments run free of charge inside the Free Tier indefinitely", "Resources provision in minutes, so failed experiments cost little", "Hardware is courier-delivered within one business week"], "answer": 2, "why": "Correct: Resources provision in minutes, so failed experiments cost little"}, {"id": 6, "domain": 1, "q": "A bank's risk team requires compute capacity split across multiple physically isolated facilities inside one geographic area. How does AWS model that requirement?", "choices": ["One Region containing several Availability Zones", "One Availability Zone containing several edge locations", "One Local Zone spanning several neighboring countries", "Several edge locations forming one Region"], "answer": 0, "why": "Correct: One Region containing several Availability Zones"}, {"id": 7, "domain": 1, "q": "Traffic keeps flowing while one Availability Zone undergoes a routine power failure. Which design property makes that possible?", "choices": ["All AZs in a Region share a single backup power grid", "Engineers manually fail over the facility during maintenance windows", "Edge locations absorb the Region's traffic during AZ outages", "AZs are isolated failure domains connected by private, low-latency links"], "answer": 3, "why": "Correct: AZs are isolated failure domains connected by private, low-latency links"}, {"id": 8, "domain": 1, "q": "A streaming platform wants its video served from cache sites near viewers worldwide instead of always from origin servers. Which AWS building block supplies those cache sites?", "choices": ["Regional Availability Zones", "CloudFront edge locations", "IAM Identity Center endpoints", "Route 53 registrar nodes"], "answer": 1, "why": "Correct: CloudFront edge locations"}, {"id": 9, "domain": 1, "q": "A workload's data may never leave Germany under the governing contract. Which factor decides the target Region?", "choices": ["The number of IAM roles already in the account", "The Region's distance from company headquarters", "Compliance and data-residency rules of that geography", "The account's Support plan tier"], "answer": 2, "why": "Correct: Compliance and data-residency rules of that geography"}, {"id": 10, "domain": 1, "q": "A consultant lists candidate criteria for picking a workload's Region. Which one is NOT a legitimate selection factor?", "choices": ["How many IAM users the account contains", "Latency from the Region to end users", "Price differences between candidate Regions", "Which services are available in each Region"], "answer": 0, "why": "Correct: How many IAM users the account contains"}, {"id": 11, "domain": 1, "q": "A two-tier application must survive the loss of one data-center building while remaining inside a single Region. Where do its instances run?", "choices": ["In one AZ, on instances twice as large", "Across Regions, giving up single-Region residency", "Inside one edge location with an on-site spare", "Across multiple Availability Zones in one Region"], "answer": 3, "why": "Correct: Across multiple Availability Zones in one Region"}, {"id": 12, "domain": 1, "q": "Which Well-Architected pillar covers measuring the environmental impact of workloads and reducing the resources wasted in running them?", "choices": ["Cost Optimization", "Sustainability", "Performance Efficiency", "Operational Excellence"], "answer": 1, "why": "Correct: Sustainability"}, {"id": 13, "domain": 1, "q": "A team's weekly review deletes unattached EBS volumes and right-sizes over-provisioned instances. Which pillar does that discipline serve?", "choices": ["Reliability", "Security", "Cost Optimization", "Sustainability"], "answer": 2, "why": "Correct: Cost Optimization"}, {"id": 14, "domain": 1, "q": "Releases ship as small reversible changes, each failure gets a review, and runbooks improve after every incident. Which pillar is the team practicing?", "choices": ["Operational Excellence", "Sustainability", "Performance Efficiency", "Cost Optimization"], "answer": 0, "why": "Correct: Operational Excellence"}, {"id": 15, "domain": 1, "q": "A workload must recover automatically from component failure and keep meeting demand that triples every December. Which pillar sets these requirements?", "choices": ["Operational Excellence", "Performance Efficiency", "Sustainability", "Reliability"], "answer": 3, "why": "Correct: Reliability"}, {"id": 16, "domain": 1, "q": "A team replaces a hand-rolled VM fleet with serverless functions and containers sized to actual load. Which pillar does this efficiency work belong to?", "choices": ["Reliability", "Performance Efficiency", "Cost Optimization", "Sustainability"], "answer": 1, "why": "Correct: Performance Efficiency"}, {"id": 17, "domain": 1, "q": "Every Friday evening an application's traffic quadruples, then returns to baseline overnight. Which approach serves that profile most cost-effectively?", "choices": ["Keeping the peak-sized fleet running every day of the week", "Purchasing Reserved Instances sized for Friday-evening peaks", "Auto Scaling that adds capacity as load rises and removes it as load falls", "Doubling every instance's size each Monday and halving it on Fridays"], "answer": 2, "why": "Correct: Auto Scaling that adds capacity as load rises and removes it as load falls"}, {"id": 18, "domain": 1, "q": "A company historically bought peak-season servers that idled 350 days a year before migrating. Which principle did the migration apply?", "choices": ["Stop guessing capacity — provision from actual, observed demand", "Buy twice the expected capacity as insurance", "Standardize on one instance size for every future workload", "Lock in three-year capacity purchases up front"], "answer": 0, "why": "Correct: Stop guessing capacity — provision from actual, observed demand"}, {"id": 19, "domain": 1, "q": "Before signing a migration plan, finance wants a month-by-month estimate of the PROPOSED AWS architecture. Which tool produces that?", "choices": ["AWS Cost Explorer", "AWS Budgets", "AWS Artifact", "AWS Pricing Calculator"], "answer": 3, "why": "Correct: AWS Pricing Calculator"}, {"id": 20, "domain": 1, "q": "A platform team adopted Amazon RDS instead of self-administering MySQL on EC2. What did they actually eliminate?", "choices": ["The need to design schemas or tune queries", "Undifferentiated infrastructure operations — engine patching, backups, and OS management", "All database licensing costs", "Responsibility for the data itself"], "answer": 1, "why": "Correct: Undifferentiated infrastructure operations — engine patching, backups, and OS management"}, {"id": 21, "domain": 1, "q": "How does running on AWS strengthen a small company's security posture?", "choices": ["Every workload receives a dedicated security engineer", "Attacks cannot reach public-facing cloud workloads at all", "Threat intelligence aggregated across AWS's customer base feeds automated protections", "Compliance reports replace customer-side technical controls"], "answer": 2, "why": "Correct: Threat intelligence aggregated across AWS's customer base feeds automated protections"}, {"id": 22, "domain": 1, "q": "A retailer must serve European users with low latency AND keep European data inside Europe. Which choice satisfies both goals?", "choices": ["Deploy into a European Region, chosen for latency and residency together", "Deploy in any Region, plus an edge location in Europe", "Deploy in us-east-1 with nightly encrypted backups to Europe", "Deploy in the Region with the lowest advertised price, wherever it is"], "answer": 0, "why": "Correct: Deploy into a European Region, chosen for latency and residency together"}, {"id": 23, "domain": 1, "q": "Which sentence pairs each cloud benefit with its actual mechanism?", "choices": ["Aggregated threat intelligence lowers unit prices; aggregated usage hardens security", "Unit prices fall because customers share one physical server pool", "Security hardens because every customer writes identical policies", "Aggregated customer usage lowers unit prices; aggregated threat intelligence hardens security"], "answer": 3, "why": "Correct: Aggregated customer usage lowers unit prices; aggregated threat intelligence hardens security"}, {"id": 24, "domain": 1, "q": "Which statement best describes why the Well-Architected Framework exists?", "choices": ["To certify that a workload is free of security vulnerabilities", "To give teams a consistent set of trade-offs to evaluate when architecting on AWS", "To replace architecture reviews with one mandatory audit form", "To catalogue every AWS service together with its pricing"], "answer": 1, "why": "Correct: To give teams a consistent set of trade-offs to evaluate when architecting on AWS"}, {"id": 25, "domain": 2, "q": "A three-tier application runs managed PostgreSQL on RDS alongside self-managed application instances on EC2. Who patches which layer?", "choices": ["The customer patches both layers, since both hold application data", "AWS patches both layers under the shared responsibility model", "AWS patches the RDS engine and its OS; the customer patches the EC2 guest OS", "The AMI vendor patches EC2 while the customer patches RDS"], "answer": 2, "why": "Correct: AWS patches the RDS engine and its OS; the customer patches the EC2 guest OS"}, {"id": 26, "domain": 2, "q": "Which duty NEVER transfers to AWS, regardless of which service the company runs?", "choices": ["Deciding how customer data is classified and protected", "Maintaining the physical security of data centers", "Keeping hypervisors patched and isolated", "Replacing failed disks inside AWS racks"], "answer": 0, "why": "Correct: Deciding how customer data is classified and protected"}, {"id": 27, "domain": 2, "q": "An auditor asks which routine task still requires the account root user even after workday sign-ins are federated. Which is it?", "choices": ["Creating an S3 bucket policy", "Rotating a Secrets Manager secret", "Attaching a role to a Lambda function", "Closing the AWS account permanently"], "answer": 3, "why": "Correct: Closing the AWS account permanently"}, {"id": 28, "domain": 2, "q": "Which devices qualify as registered MFA factors in an AWS account?", "choices": ["Security groups and network ACLs enforcing packet rules", "Hardware key fobs and virtual authenticator apps generating one-time codes", "KMS keys and CloudTrail trails anchoring the audit trail", "Secrets Manager entries and SSM parameters"], "answer": 1, "why": "Correct: Hardware key fobs and virtual authenticator apps generating one-time codes"}, {"id": 29, "domain": 2, "q": "A developer needs read access to exactly one S3 bucket. Which IAM policy best expresses least privilege?", "choices": ["Attach AdministratorAccess now and revisit permissions next quarter", "Allow s3:* on every bucket to avoid future friction", "Allow s3:GetObject on that specific bucket and nothing else", "Reuse the root account's permissions for the developer"], "answer": 2, "why": "Correct: Allow s3:GetObject on that specific bucket and nothing else"}, {"id": 30, "domain": 2, "q": "Hundreds of warehouse devices push telemetry to AWS around the clock. Which credential design avoids embedding long-lived keys in the devices?", "choices": ["Assuming an IAM role that exchanges short-lived temporary credentials", "Embedding one shared IAM user's access key in the firmware", "Signing requests with the account root password", "Rotating the access key manually every morning at 06:00"], "answer": 0, "why": "Correct: Assuming an IAM role that exchanges short-lived temporary credentials"}, {"id": 31, "domain": 2, "q": "Why does an IAM administrator prefer groups over editing user policies one by one?", "choices": ["Groups hold the users' passwords in encrypted storage", "Groups enroll members in MFA automatically", "Groups convert IAM users into federated identities", "Policy changes apply once per group and inherit through membership"], "answer": 3, "why": "Correct: Policy changes apply once per group and inherit through membership"}, {"id": 32, "domain": 2, "q": "An identity policy explicitly allows an action while another attached policy explicitly denies the same action. What is the outcome?", "choices": ["Allowed — the more recently updated policy wins", "Denied — an explicit deny overrides every matching allow", "Allowed — allow statements outweigh deny statements", "The conflict is parked for AWS support review"], "answer": 1, "why": "Correct: Denied — an explicit deny overrides every matching allow"}, {"id": 33, "domain": 2, "q": "A freshly created IAM user with no policies attempts to list the account's buckets. What happens?", "choices": ["The listing succeeds read-only until a policy says otherwise", "The user is prompted to accept the customer agreement", "AccessDenied — with nothing granting access, every request starts denied", "The request is elevated to the root user and then executed"], "answer": 2, "why": "Correct: AccessDenied — with nothing granting access, every request starts denied"}, {"id": 34, "domain": 2, "q": "Which settings does an account-level password policy actually control?", "choices": ["Minimum length, character classes, and reuse or rotation rules for user passwords", "Encryption applied to objects in S3 buckets", "Which MFA devices the root user may register", "The CIDR ranges of newly created subnets"], "answer": 0, "why": "Correct: Minimum length, character classes, and reuse or rotation rules for user passwords"}, {"id": 35, "domain": 2, "q": "Employees should sign in once with corporate directory credentials and reach several AWS accounts. Which service was built for this?", "choices": ["Amazon Cognito — pools for customer-facing applications", "AWS KMS with a multi-Region key", "AWS Directory Service without any federation", "IAM Identity Center — workforce single sign-on across accounts"], "answer": 3, "why": "Correct: IAM Identity Center — workforce single sign-on across accounts"}, {"id": 36, "domain": 2, "q": "A consumer app with millions of end customers needs its own sign-up and sign-in. Which service fits — and why not the one used for workforce SSO?", "choices": ["IAM Identity Center — it scales better for public audiences than Cognito", "Amazon Cognito — it manages customer identities; IAM Identity Center is for workforce access into AWS accounts", "AWS Secrets Manager — customer passwords are, technically, secrets", "AWS CloudTrail — it authenticates the app's API calls"], "answer": 1, "why": "Correct: Amazon Cognito — it manages customer identities; IAM Identity Center is for workforce access into AWS accounts"}, {"id": 37, "domain": 2, "q": "Which statement about IAM roles is correct?", "choices": ["Roles hold permanent passwords for each service they touch", "Only the root user can assume a role in an account", "Roles issue temporary credentials that workloads or users assume, with nothing stored long-term", "Roles are the organizational unit sitting above IAM groups"], "answer": 2, "why": "Correct: Roles issue temporary credentials that workloads or users assume, with nothing stored long-term"}, {"id": 38, "domain": 2, "q": "Data crossing the internet from a user's browser to an AWS service endpoint must resist interception. Which control is present at every service endpoint?", "choices": ["HTTPS over TLS terminating at the endpoint", "Availability Zone redundancy", "Per-subnet NACL rule sets", "S3 lifecycle transitions"], "answer": 0, "why": "Correct: HTTPS over TLS terminating at the endpoint"}, {"id": 39, "domain": 2, "q": "An attacker obtains a raw volume snapshot file outside any AWS account. Which control makes the contained data unreadable to them?", "choices": ["Multi-factor authentication on the console user", "A Route 53 health check on the application", "S3 Transfer Acceleration on the bucket", "Encryption at rest with keys the attacker does not hold"], "answer": 3, "why": "Correct: Encryption at rest with keys the attacker does not hold"}, {"id": 40, "domain": 2, "q": "Nobody touches the encryption settings as an object lands in a bucket. What state is the object in?", "choices": ["Plaintext until an administrator enables encryption on the bucket", "Encrypted automatically with SSE-S3 managed keys", "Rejected by the upload with an AccessDenied error", "Encrypted only after versioning is switched on"], "answer": 1, "why": "Correct: Encrypted automatically with SSE-S3 managed keys"}, {"id": 41, "domain": 2, "q": "What does AWS KMS actually do for an application?", "choices": ["Scans EBS volumes for malware between scheduled backups", "Moves S3 objects between storage classes on a schedule", "Creates and stores keys, controls their use through key policies, and logs every use in CloudTrail", "Provisions TLS certificates for public DNS names"], "answer": 2, "why": "Correct: Creates and stores keys, controls their use through key policies, and logs every use in CloudTrail"}, {"id": 42, "domain": 2, "q": "A customer-managed symmetric KMS key sits untouched since creation. What does automatic rotation do?", "choices": ["Rotates its key material every 365 days while the key ID stays the same", "Rotates its key material every 90 days and issues a new key ID each time", "Leaves the key material unchanged until an operator clicks Rotate", "Rotates asymmetric key pairs on the same annual schedule"], "answer": 0, "why": "Correct: Rotates its key material every 365 days while the key ID stays the same"}, {"id": 43, "domain": 2, "q": "An investigator must prove who deleted a production bucket, and from which IP address, two months ago. Which service holds that evidence?", "choices": ["AWS Config — the timeline of resource configuration states", "Amazon Inspector — the CVE scan history of the account", "AWS Trusted Advisor — the service-limit check log", "CloudTrail — the record of API calls with caller identity and source IP"], "answer": 3, "why": "Correct: CloudTrail — the record of API calls with caller identity and source IP"}, {"id": 44, "domain": 2, "q": "A developer opens the CloudTrail console today and queries Event history without ever creating a trail. How deep can they look back?", "choices": ["Management events for the account's entire lifetime", "90 days of past management events, no further", "24 hours, extendable by opening a support case", "All events forever, provided they were delivered somewhere"], "answer": 1, "why": "Correct: 90 days of past management events, no further"}, {"id": 45, "domain": 2, "q": "Which pairing of service to purpose is right?", "choices": ["CloudTrail records HOW a resource was configured; AWS Config records WHO called an API", "Both record the same API calls; Config adds remediation buttons", "CloudTrail records WHO called an API; AWS Config records HOW a resource was configured", "CloudTrail covers compute only; Config covers storage only"], "answer": 2, "why": "Correct: CloudTrail records WHO called an API; AWS Config records HOW a resource was configured"}, {"id": 46, "domain": 2, "q": "Threat hunters want machine-learning detectors fed by CloudTrail, VPC flow logs, and DNS logs to flag compromised credentials. Which service?", "choices": ["Amazon GuardDuty", "AWS Security Hub", "Amazon Macie", "Amazon Inspector"], "answer": 0, "why": "Correct: Amazon GuardDuty"}, {"id": 47, "domain": 2, "q": "Patching teams want continuous CVE scanning across EC2 instances and container images in ECR. Which service does that?", "choices": ["Amazon GuardDuty", "AWS Artifact", "AWS Security Hub", "Amazon Inspector"], "answer": 3, "why": "Correct: Amazon Inspector"}, {"id": 48, "domain": 2, "q": "Compliance knows sensitive customer records sit somewhere among thousands of S3 objects. Which service locates the PII?", "choices": ["Amazon Inspector — scanning bucket policies for vulnerabilities", "Amazon Macie — pattern matching and ML to discover sensitive data in S3", "AWS Config — recording bucket encryption settings over time", "Amazon GuardDuty — alerting on unusual bucket access"], "answer": 1, "why": "Correct: Amazon Macie — pattern matching and ML to discover sensitive data in S3"}, {"id": 49, "domain": 2, "q": "A CISO wants GuardDuty, Inspector, and Macie findings consolidated on one pane and scored against security standards. Which service assembles that?", "choices": ["AWS CloudTrail", "Amazon CloudWatch alone", "AWS Security Hub", "AWS Organizations"], "answer": 2, "why": "Correct: AWS Security Hub"}, {"id": 50, "domain": 2, "q": "An auditor requests AWS's PCI compliance documentation and a signed agreement. Which self-service route delivers both?", "choices": ["Download from AWS Artifact — no support ticket required", "Email the account manager and wait for attachments", "Request them through the highest support tier's chat", "Reconstruct them from CloudTrail Lake queries"], "answer": 0, "why": "Correct: Download from AWS Artifact — no support ticket required"}, {"id": 51, "domain": 2, "q": "Which layer-7 control blocks injection-pattern web requests in front of an Application Load Balancer?", "choices": ["Shield Standard's default volumetric filtering", "A Network ACL denying port 80 inbound", "GuardDuty findings piped into EventBridge", "A WAF web ACL with managed rules attached to the load balancer"], "answer": 3, "why": "Correct: A WAF web ACL with managed rules attached to the load balancer"}, {"id": 52, "domain": 2, "q": "Which protection runs automatically for every AWS customer at no additional charge?", "choices": ["Shield Advanced with a 24/7 response team and cost protection", "Shield Standard — always-on defenses against common network and transport DDoS", "WAF with every managed rule group pre-enabled", "GuardDuty enabled account-wide on the free tier"], "answer": 1, "why": "Correct: Shield Standard — always-on defenses against common network and transport DDoS"}, {"id": 53, "domain": 2, "q": "Where does a database password that must rotate itself every 30 days belong?", "choices": ["SSM Parameter Store SecureString edited by hand each month", "A comment block inside the deployment script", "AWS Secrets Manager — storage plus scheduled automatic rotation", "An IAM policy variable embedded in the role"], "answer": 2, "why": "Correct: AWS Secrets Manager — storage plus scheduled automatic rotation"}, {"id": 54, "domain": 2, "q": "A company operates under GDPR in Europe and healthcare privacy rules in the US. How should it plan compliance mapping on AWS?", "choices": ["Map each geography-and-industry obligation to AWS compliance programs and Artifact agreements", "Consolidate every workload into one Region satisfying both regimes", "Offload compliance entirely to AWS under the shared responsibility model", "Assume one certificate covers every regulation worldwide"], "answer": 0, "why": "Correct: Map each geography-and-industry obligation to AWS compliance programs and Artifact agreements"}, {"id": 55, "domain": 3, "q": "Traffic to a web fleet must spread across instances in two AZs, and the fleet must grow and shrink with demand. Which pairing handles both?", "choices": ["VPC peering between the AZs plus an NACL allowing all traffic", "Route 53 health checks plus an IAM role per instance", "An S3 bucket with cross-AZ replication plus lifecycle rules", "An Elastic Load Balancer distributing traffic plus an Auto Scaling group resizing the fleet"], "answer": 3, "why": "Correct: An Elastic Load Balancer distributing traffic plus an Auto Scaling group resizing the fleet"}, {"id": 56, "domain": 3, "q": "An API tier routes /orders to one service and /users to another behind a single load balancer. Which load balancer type?", "choices": ["Network Load Balancer — it hashes TCP flows across targets", "Application Load Balancer — layer-7 routing on request paths and headers", "Classic Load Balancer limited to pass-through HTTPS", "Gateway Load Balancer placed inline in the subnet"], "answer": 1, "why": "Correct: Application Load Balancer — layer-7 routing on request paths and headers"}, {"id": 57, "domain": 3, "q": "A market-data feed must sustain extreme TCP throughput with very low latency. Which load balancer fits the layer-4 profile?", "choices": ["Application Load Balancer", "Gateway Load Balancer", "Network Load Balancer", "Classic Load Balancer"], "answer": 2, "why": "Correct: Network Load Balancer"}, {"id": 58, "domain": 3, "q": "A nightly export needs 40 minutes of compute per run with no server for the team to manage. Which option fits?", "choices": ["Amazon ECS on Fargate — containers run without any instance fleet", "AWS Lambda — invocations are capped at 15 minutes", "EC2 Reserved Instances — provisioned but idle between nightly runs", "Amazon S3 batch operations — they process objects, not compute jobs"], "answer": 0, "why": "Correct: Amazon ECS on Fargate — containers run without any instance fleet"}, {"id": 59, "domain": 3, "q": "An operations team schedules Docker container tasks on a fleet of EC2 instances whose capacity they control themselves. Which orchestration service?", "choices": ["Amazon EKS with Fargate profiles only", "EC2 Auto Scaling without a container layer", "AWS Storage Gateway for the task data", "Amazon ECS with the EC2 launch type"], "answer": 3, "why": "Correct: Amazon ECS with the EC2 launch type"}, {"id": 60, "domain": 3, "q": "Which option lets a team run containers while AWS operates BOTH the container instances and the underlying servers?", "choices": ["Amazon ECS with the EC2 launch type and a large Auto Scaling group", "AWS Fargate behind ECS or EKS tasks", "Amazon EKS with customer-managed worker nodes", "Docker installed on one EC2 instance with cron scheduling"], "answer": 1, "why": "Correct: AWS Fargate behind ECS or EKS tasks"}, {"id": 61, "domain": 3, "q": "A platform team must run certified Kubernetes with AWS managing the control plane while they keep operating the worker nodes. Which service?", "choices": ["Amazon ECS", "AWS Fargate", "Amazon EKS", "Amazon ECR"], "answer": 2, "why": "Correct: Amazon EKS"}, {"id": 62, "domain": 3, "q": "A startup deploys a Python web app and wants capacity, load balancing, and health monitoring arranged automatically — without losing access to the underlying resources. Which service?", "choices": ["AWS Elastic Beanstalk", "AWS CloudFormation", "Amazon S3 static website hosting", "A hand-built EC2 fleet behind a load balancer"], "answer": 0, "why": "Correct: AWS Elastic Beanstalk"}, {"id": 63, "domain": 3, "q": "A manufacturer must run AWS API-compatible compute physically inside its factory, where data cannot leave and round-trip latency must be near zero. Which offering?", "choices": ["AWS Snowball Edge — an appliance for bulk data transfer", "AWS Local Zones — Region extensions in metro areas", "Amazon WorkSpaces — managed desktops in a Region", "AWS Outposts — AWS-designed hardware and services on customer premises"], "answer": 3, "why": "Correct: AWS Outposts — AWS-designed hardware and services on customer premises"}, {"id": 64, "domain": 3, "q": "A compliance archive is written once, read at most once a year, and retrieval time of hours is acceptable. Which storage class minimizes cost?", "choices": ["S3 Standard-IA", "S3 Glacier Deep Archive", "S3 One Zone-IA", "S3 Standard"], "answer": 1, "why": "Correct: S3 Glacier Deep Archive"}, {"id": 65, "domain": 3, "q": "Objects drop out of active use after two months. What moves them to a cheaper class automatically, with no operator involvement?", "choices": ["A Route 53 weighted routing policy", "An EC2 Auto Scaling scheduled action", "An S3 lifecycle policy transitioning objects by age", "An IAM policy condition keyed on object age"], "answer": 2, "why": "Correct: An S3 lifecycle policy transitioning objects by age"}, {"domain": 1, "q": "A company currently purchases servers each year and wants to move to AWS so it no longer needs large upfront hardware investments. Which cloud benefit does this describe?", "choices": ["Trading capital expense for variable expense", "Achieving economies of scale", "Increasing speed and agility", "Training staff on new hardware"], "answer": 0, "why": "Cloud converts upfront capital expense into pay-as-you-go operational expense."}, {"domain": 1, "q": "A company's web traffic doubles during holiday sales and returns to normal afterward. Which AWS feature lets it add and remove capacity automatically to match demand?", "choices": ["Elasticity", "High durability", "Economies of scale", "Data residency"], "answer": 0, "why": "Elasticity scales resources in and out with demand so the company pays only for what it uses."}, {"domain": 1, "q": "A company must keep all customer data stored only within Germany to meet legal requirements. Which factor should guide its choice of AWS Region?", "choices": ["Data residency and compliance requirements", "Proximity to the company headquarters", "Availability of edge locations in the Region", "The total number of Availability Zones worldwide"], "answer": 0, "why": "Compliance and data residency obligations can restrict which Regions may store the data."}, {"domain": 1, "q": "Which AWS feature or resource provides physically isolated infrastructure with independent power, cooling, and networking within a Region?", "choices": ["An Availability Zone", "An edge location", "A Local Zone", "A VPC subnet"], "answer": 0, "why": "Each Availability Zone is a separate group of data centers with independent power, cooling, and networking."}, {"domain": 1, "q": "Which design practice improves an application's availability on AWS?", "choices": ["Deploying the application across multiple Availability Zones", "Deploying the application on a single large instance in one zone", "Storing all data on a single Amazon EBS volume", "Running the web tier and database on one instance"], "answer": 0, "why": "Deploying across multiple Availability Zones removes single points of failure and keeps the application available during zone failures."}, {"domain": 1, "q": "A media company wants users worldwide to download large video files with the lowest possible latency. Which AWS feature stores copies of content at locations close to users?", "choices": ["Edge locations used by Amazon CloudFront", "AWS Direct Connect locations", "Availability Zones in one Region", "AWS Outposts racks"], "answer": 0, "why": "Edge locations cache content near users to reduce latency for content delivery."}, {"domain": 1, "q": "A global application needs the lowest latency for users in Asia. Which factor is most important when selecting the Region to deploy in?", "choices": ["Distance and network latency to the users", "The Region's launch date", "The number of AWS services launched before the Region", "The number of edge locations in other Regions"], "answer": 0, "why": "Latency to end users is a primary Region selection factor for user-facing workloads."}, {"domain": 1, "q": "Which factor should NOT influence a company's choice of AWS Region for a new workload?", "choices": ["The cost of office space near AWS offices", "Compliance and data governance requirements", "Latency to end users", "Service availability in the Region"], "answer": 0, "why": "Office real estate costs do not affect workload performance or compliance, unlike the other Region selection factors."}, {"domain": 1, "q": "A company replaced manual runbooks and console clicks with infrastructure as code and automated deployments. Which Well-Architected pillar does this demonstrate?", "choices": ["Operational excellence", "Cost optimization", "Sustainability", "Fault tolerance"], "answer": 0, "why": "Operational excellence focuses on automating operations and continuously improving processes."}, {"domain": 1, "q": "An architect designs a system that recovers automatically from failures and regularly tests backup and restore procedures. Which Well-Architected pillar is being applied?", "choices": ["Reliability", "Performance efficiency", "Security", "Operational excellence"], "answer": 0, "why": "The reliability pillar covers recovering from failures and testing recovery procedures."}, {"domain": 1, "q": "A team grants each employee only the minimum permissions needed to perform their job. Which Well-Architected pillar does this follow?", "choices": ["Security", "Cost optimization", "Reliability", "Sustainability"], "answer": 0, "why": "Applying least privilege is a core practice of the security pillar."}, {"domain": 1, "q": "A startup right-sizes instances, uses Auto Scaling, and shuts down unused test environments. Which Well-Architected pillar does this reflect?", "choices": ["Cost optimization", "Security", "Reliability", "Operational excellence"], "answer": 0, "why": "Right-sizing and eliminating waste are cost optimization practices."}, {"domain": 1, "q": "A company selects serverless and managed services so it can focus on its application instead of server management. Which Well-Architected pillar does this support?", "choices": ["Performance efficiency", "Sustainability", "Security", "Reliability"], "answer": 0, "why": "Performance efficiency includes using managed and serverless services that match technology to the workload."}, {"domain": 1, "q": "A company measures the carbon impact of its workloads and consolidates underused servers to reduce energy use. Which Well-Architected pillar does this address?", "choices": ["Sustainability", "Cost optimization", "Operational excellence", "Reliability"], "answer": 0, "why": "The sustainability pillar focuses on minimizing environmental impact and resource consumption."}, {"domain": 1, "q": "Which choice best describes high availability?", "choices": ["A system remains operational and accessible with minimal downtime even when components fail", "A system is protected from all unauthorized access", "A system stores three copies of data in one data center", "A system doubles throughput after a hardware upgrade"], "answer": 0, "why": "High availability means the system stays accessible despite component failures, with minimal downtime."}, {"domain": 1, "q": "A system continues operating even when one server fails, without data loss. Which concept does this describe?", "choices": ["Fault tolerance", "Elasticity", "Scalability", "Agility"], "answer": 0, "why": "Fault tolerance lets a workload continue operating through component failures."}, {"domain": 1, "q": "How do AWS customers benefit from the economies of scale of the AWS Cloud?", "choices": ["They pay lower pay-as-you-go prices because AWS aggregates usage from many customers", "They receive free EC2 instances for the first year", "They avoid paying any charges for data transfer", "They get exclusive access to newer hardware than other customers"], "answer": 0, "why": "Aggregated usage across many customers lets AWS achieve lower variable costs that are passed on as lower prices."}, {"domain": 1, "q": "A company wants to deploy its application to new international markets within days instead of months of data center work. Which cloud benefit does this illustrate?", "choices": ["Increased speed and agility", "Lower audit requirements", "Elimination of all security controls", "Reduced need for monitoring"], "answer": 0, "why": "Cloud resources can be provisioned in minutes, giving companies speed and agility to expand."}, {"domain": 1, "q": "Which task does AWS perform on behalf of customers using Amazon RDS?", "choices": ["Operating system patching and automated backups", "Writing the application's business logic", "Configuring the customer's IAM users", "Designing the customer's database schema"], "answer": 0, "why": "Managed services like RDS handle OS patching, backups, and maintenance, reducing operational overhead."}, {"domain": 1, "q": "With the AWS pay-as-you-go pricing model, a company pays only for:", "choices": ["The resources it actually uses, with no long-term commitment", "A fixed monthly fee regardless of usage", "One year of capacity purchased in advance", "All services in every Region whether used or not"], "answer": 0, "why": "Pay-as-you-go billing charges only for consumed resources and avoids long-term commitments."}, {"domain": 1, "q": "Which task is the customer's responsibility under the AWS Shared Responsibility Model for Amazon EC2?", "choices": ["Patching the guest operating system", "Patching the hypervisor software", "Replacing failed physical disks", "Securing the physical data center"], "answer": 0, "why": "Customers patch the guest OS and applications; AWS is responsible for the underlying infrastructure."}, {"domain": 1, "q": "A company wants to experiment with new product ideas and launch prototypes in hours rather than waiting weeks for hardware procurement. Which cloud benefit applies?", "choices": ["Eliminating the need to guess capacity and procure hardware in advance", "Locking in fixed capacity for three years", "Purchasing servers at a discount each quarter", "Reducing the number of applications the company runs"], "answer": 0, "why": "On-demand provisioning removes hardware procurement delays so teams can experiment and launch quickly."}, {"domain": 1, "q": "Which statement about AWS Regions is correct?", "choices": ["Each Region is a separate geographic area containing multiple isolated Availability Zones", "Each Region contains exactly one data center", "All Regions are located in the United States", "Regions share a single physical power grid"], "answer": 0, "why": "A Region is a geographic area with multiple, isolated Availability Zones."}, {"domain": 1, "q": "A company hosts an application in one Availability Zone and wants to improve resilience against the failure of that zone. What should it do?", "choices": ["Deploy the application across multiple Availability Zones in the same Region", "Move the application to a single larger instance", "Store all backups on the same server in the same zone", "Add more memory to the existing servers"], "answer": 0, "why": "A multi-AZ deployment protects the application against the failure of any single Availability Zone."}, {"domain": 3, "q": "A company runs a small stateless image-processing function that must handle unpredictable bursts of requests with no server administration. Which service fits best?", "choices": ["AWS Lambda", "Amazon EC2 with Auto Scaling", "Amazon EKS", "AWS Direct Connect"], "answer": 0, "why": "Lambda runs code on demand with no servers to manage and scales automatically with request volume."}, {"domain": 3, "q": "A team wants to run Docker containers on AWS without provisioning or managing any servers or clusters. Which compute option should it choose?", "choices": ["AWS Fargate", "Amazon EC2 Reserved Instances", "AWS Snowball Edge", "Amazon Redshift"], "answer": 0, "why": "Fargate is a serverless compute engine for containers that removes cluster and server management."}, {"domain": 3, "q": "A company must migrate an existing Kubernetes cluster to AWS while keeping its standard Kubernetes tooling. Which managed service should it use?", "choices": ["Amazon EKS", "AWS Lambda", "Amazon S3", "Amazon RDS"], "answer": 0, "why": "EKS is a managed Kubernetes control plane that supports standard Kubernetes tooling."}, {"domain": 3, "q": "A developer wants to deploy a new web application quickly and let AWS manage capacity, load balancing, and automatic scaling while managing only the application code. Which service fits?", "choices": ["AWS Elastic Beanstalk", "Amazon EC2 with custom AMIs", "AWS Outposts", "Amazon S3"], "answer": 0, "why": "Elastic Beanstalk handles provisioning, load balancing, and scaling while the developer manages only code."}, {"domain": 3, "q": "A research team stores genomic data that is accessed once or twice per year and must be archived for 10 years at the lowest possible cost. Which S3 storage class fits?", "choices": ["S3 Glacier Deep Archive", "S3 Standard", "S3 One Zone-IA", "S3 Standard-IA"], "answer": 0, "why": "S3 Glacier Deep Archive offers the lowest storage cost for data accessed once or twice a year."}, {"domain": 3, "q": "A video editing application needs a shared POSIX file system that thousands of Linux EC2 instances can mount concurrently and that grows and shrinks automatically. Which service fits?", "choices": ["Amazon EFS", "Amazon EBS", "Amazon S3 Standard-IA", "AWS Snowcone"], "answer": 0, "why": "EFS provides elastic shared POSIX file storage that many instances can mount concurrently."}, {"domain": 3, "q": "Which storage service provides block-level volumes that attach to a single EC2 instance and are ideal for boot volumes and databases?", "choices": ["Amazon EBS", "Amazon EFS", "Amazon S3 Glacier", "Amazon DynamoDB"], "answer": 0, "why": "EBS delivers persistent block storage volumes for individual EC2 instances, including boot volumes."}, {"domain": 3, "q": "A company's Windows file servers use SMB shares and Active Directory integration and must move to AWS with native Windows file semantics. Which service fits?", "choices": ["Amazon FSx for Windows File Server", "Amazon EFS", "Amazon S3", "Amazon EBS"], "answer": 0, "why": "FSx for Windows File Server provides fully managed SMB file shares with Active Directory integration."}, {"domain": 3, "q": "An EC2 instance in a private subnet must download security updates from the internet without allowing inbound connections from the internet. Which component enables this?", "choices": ["A NAT gateway in a public subnet", "An internet gateway attached to the private subnet", "A security group allowing all inbound traffic", "A VPC peering connection"], "answer": 0, "why": "A NAT gateway lets private subnet instances initiate outbound internet traffic while blocking unsolicited inbound connections."}, {"domain": 3, "q": "Which security feature is stateless, operates at the subnet level, and can explicitly deny traffic by rule number?", "choices": ["A network ACL", "A security group", "AWS WAF", "A NAT gateway"], "answer": 0, "why": "Network ACLs are stateless, subnet-level firewalls that support explicit deny rules evaluated by rule number."}, {"domain": 3, "q": "A company needs a quick, encrypted connection from its on-premises network to its VPC and can accept traffic traversing the public internet. Which service fits?", "choices": ["AWS Site-to-Site VPN", "AWS Direct Connect", "Amazon Route 53", "AWS Snowball"], "answer": 0, "why": "Site-to-Site VPN creates an encrypted IPsec tunnel over the internet and can be established in minutes rather than months."}, {"domain": 3, "q": "A company wants DNS queries for its web application routed to the AWS Region with the lowest latency for each user. Which Route 53 routing policy fits?", "choices": ["Latency-based routing", "Simple routing", "Weighted routing", "Failover routing"], "answer": 0, "why": "Latency-based routing directs each user to the Region that provides the lowest latency for that user."}, {"domain": 3, "q": "A company wants to deliver static website content to global users with low latency through a content delivery network backed by S3. Which service fits?", "choices": ["Amazon CloudFront", "Amazon EBS", "AWS Direct Connect", "Amazon Redshift"], "answer": 0, "why": "CloudFront caches content at edge locations worldwide for low-latency global delivery."}, {"domain": 3, "q": "A company runs a production MySQL database on RDS and must ensure the database remains available if the primary instance fails. Which RDS feature provides automatic failover to a standby instance?", "choices": ["Multi-AZ deployment", "Read replicas", "Aurora Serverless", "Elastic Beanstalk"], "answer": 0, "why": "Multi-AZ deployments automatically fail over to a synchronous standby in another Availability Zone."}, {"domain": 3, "q": "A company needs a MySQL-compatible relational database that scales automatically and delivers higher performance than standard MySQL. Which service fits?", "choices": ["Amazon Aurora", "Amazon Redshift", "Amazon DynamoDB", "Amazon FSx for Lustre"], "answer": 0, "why": "Aurora is MySQL-compatible, scales automatically, and delivers performance up to five times standard MySQL."}, {"domain": 3, "q": "An application needs a key-value database that handles millions of requests per second with single-digit millisecond latency and no server administration. Which service fits?", "choices": ["Amazon DynamoDB", "Amazon RDS for MySQL", "Amazon Redshift", "Amazon EFS"], "answer": 0, "why": "DynamoDB is a serverless key-value database that delivers single-digit millisecond performance at any scale."}, {"domain": 3, "q": "An order-processing system receives sudden spikes of messages that a slower downstream service consumes later. Which service decouples the components with a message queue?", "choices": ["Amazon SQS", "Amazon SNS", "Amazon EventBridge", "AWS Step Functions"], "answer": 0, "why": "SQS queues messages so producers and consumers can operate independently of each other."}, {"domain": 3, "q": "A company wants to send one notification about each new order to an email list, an SMS list, and an application endpoint simultaneously. Which service fits?", "choices": ["Amazon SNS", "Amazon SQS", "AWS Batch", "Amazon CloudWatch Logs"], "answer": 0, "why": "SNS fans out each published message to multiple subscribed endpoints at once."}, {"domain": 3, "q": "A data team must physically transfer 50 PB of on-premises data to AWS and cannot use the internet. Which service fits?", "choices": ["AWS Snowmobile", "AWS Site-to-Site VPN", "Amazon S3 Transfer Acceleration", "Amazon DataSync"], "answer": 0, "why": "Snowmobile is a truck-based transfer service designed for petabyte to exabyte-scale offline data migration."}, {"domain": 3, "q": "A company must run AWS infrastructure on-premises in its own data center to meet low-latency and data-locality requirements. Which service fits?", "choices": ["AWS Outposts", "AWS Snowball Edge", "Amazon CloudFront edge locations", "Amazon ECS on EC2"], "answer": 0, "why": "Outposts delivers racks of AWS compute and storage that run on-premises with native AWS APIs."}, {"domain": 3, "q": "An operations team wants a single service to collect metrics, set alarms, and view logs from its AWS resources. Which service fits?", "choices": ["Amazon CloudWatch", "AWS CloudTrail", "Amazon SNS", "AWS Config"], "answer": 0, "why": "CloudWatch collects metrics and logs and raises alarms based on thresholds."}, {"domain": 2, "q": "A company wants to ensure that its AWS account root user credentials are protected. Which combination of actions should the company take?", "choices": ["Enable MFA on the root user and delete its access keys", "Use the root user for daily administration and enable CloudTrail", "Create an IAM user with AdministratorAccess and store root credentials in a vault", "Enable AWS WAF on the root user login page"], "answer": 0, "why": "Best practice is to enable MFA on the root user, avoid using it for daily tasks, and delete or lock its access keys."}, {"domain": 2, "q": "Which AWS service provides a single place to track user activity and API usage across AWS accounts?", "choices": ["AWS CloudTrail", "Amazon CloudWatch", "AWS Config", "Amazon Inspector"], "answer": 0, "why": "CloudTrail records API calls and user activity, supporting audit and compliance across accounts."}, {"domain": 2, "q": "Under the AWS shared responsibility model, who is responsible for patching the guest operating system on an Amazon EC2 instance?", "choices": ["AWS", "The customer", "AWS and the customer share it equally with no customer action required", "The EC2 hardware provider"], "answer": 1, "why": "Customers are responsible for security in the cloud, including patching guest OS and applications."}, {"domain": 2, "q": "A security team wants fully managed detection of suspicious account and network activity across its AWS environment. Which service should they use?", "choices": ["Amazon GuardDuty", "Amazon Inspector", "AWS Shield", "Amazon Macie"], "answer": 0, "why": "GuardDuty is a threat detection service that analyzes CloudTrail, VPC Flow Logs, and DNS logs for malicious activity."}, {"domain": 2, "q": "Which service should be used to identify personally identifiable information (PII) stored in Amazon S3 buckets?", "choices": ["Amazon Macie", "AWS WAF", "AWS KMS", "Amazon Detective"], "answer": 0, "why": "Macie uses machine learning to discover and classify sensitive data such as PII in S3."}, {"domain": 2, "q": "A company needs to store database credentials securely and enable automatic rotation every 30 days. Which service should be used?", "choices": ["AWS KMS", "AWS Secrets Manager", "AWS Systems Manager Parameter Store Secure strings with manual rotation", "Amazon S3 with SSE-KMS"], "answer": 1, "why": "Secrets Manager stores, retrieves, and automatically rotates secrets such as database credentials."}, {"domain": 2, "q": "Which AWS service continuously records resource configuration changes and evaluates them against compliance rules?", "choices": ["AWS CloudTrail", "AWS Config", "AWS Security Hub", "AWS Artifact"], "answer": 1, "why": "Config tracks resource configurations and evaluates compliance against defined rules; CloudTrail records API activity."}, {"domain": 2, "q": "A company wants a centralized view of security alerts and compliance posture across multiple AWS accounts. Which service provides this?", "choices": ["AWS Security Hub", "Amazon GuardDuty", "AWS Trusted Advisor", "AWS Audit Manager"], "answer": 0, "why": "Security Hub aggregates findings from GuardDuty, Inspector, Macie, and other services into one console."}, {"domain": 2, "q": "Which task is the responsibility of AWS under the shared responsibility model?", "choices": ["Applying updates to Lambda function code", "Encrypting data written to DynamoDB tables by default at the hardware level", "Configuring VPC security group rules", "Managing IAM user passwords"], "answer": 1, "why": "AWS is responsible for underlying infrastructure security, including encryption of physical devices and some default service-level protections."}, {"domain": 2, "q": "A company must comply with PCI DSS and needs AWS audit artifacts and compliance documentation. Which service provides these?", "choices": ["AWS Artifact", "AWS Config", "AWS Control Tower", "AWS KMS"], "answer": 0, "why": "Artifact provides on-demand access to AWS compliance reports and agreements such as PCI DSS attestation."}, {"domain": 2, "q": "Which principle should guide IAM policy design to minimize security risk?", "choices": ["Grant all users AdministratorAccess and audit later", "Grant least privilege, giving only the permissions required to perform tasks", "Use the root user for all operations so policies are not needed", "Attach permissions to users rather than groups for finer control"], "answer": 1, "why": "Least privilege ensures users and roles have only the minimum permissions needed."}, {"domain": 2, "q": "A company wants to provide temporary credentials to federated employees from its corporate identity provider without creating IAM users. What should it use?", "choices": ["IAM roles", "IAM groups", "IAM access keys", "Amazon Cognito user pools"], "answer": 0, "why": "IAM roles allow federated identity federation and provide temporary credentials without static keys."}, {"domain": 2, "q": "What is the primary difference between Amazon Cognito and IAM Identity Center?", "choices": ["Cognito manages workforce access to AWS accounts; IAM Identity Center manages application user sign-up and sign-in", "IAM Identity Center manages workforce access to AWS accounts; Cognito manages customer identity for web and mobile applications", "Both services provide identical functionality", "Cognito is used only for MFA; IAM Identity Center is used only for encryption"], "answer": 1, "why": "IAM Identity Center (AWS SSO) handles workforce users across AWS accounts; Cognito handles customer (external) identities for apps."}, {"domain": 2, "q": "Which feature protects against DDoS attacks by automatically absorbing large volumes of traffic at the edge of the network?", "choices": ["AWS Shield Standard", "AWS KMS", "AWS Config", "Amazon Inspector"], "answer": 0, "why": "Shield Standard is automatically included at no cost and protects against common network and transport layer DDoS attacks."}, {"domain": 2, "q": "A security officer wants to protect a public web application from SQL injection and cross-site scripting. Which service should be used?", "choices": ["AWS WAF", "AWS Shield Advanced", "Amazon Inspector", "AWS Firewall Manager only"], "answer": 0, "why": "WAF inspects web requests and applies rules against common exploits such as SQL injection and XSS."}, {"domain": 2, "q": "What does encryption in transit protect against?", "choices": ["Physical theft of storage devices", "Interception of data while it moves across networks", "Unauthorized deletion of data at rest", "Loss of encryption keys"], "answer": 1, "why": "Encryption in transit (for example TLS) protects data as it travels between systems."}, {"domain": 2, "q": "Which service can be used to create and manage cryptographic keys for encrypting data at rest?", "choices": ["AWS KMS", "AWS CloudHSM only", "AWS Secrets Manager", "Amazon Inspector"], "answer": 0, "why": "KMS is the managed service for creating and controlling encryption keys used across AWS services."}, {"domain": 2, "q": "A company wants to identify software vulnerabilities running on its EC2 instances and container images. Which service should it use?", "choices": ["Amazon Inspector", "AWS Shield", "AWS WAF", "Amazon Macie"], "answer": 0, "why": "Inspector automatically scans EC2 instances and container images for software vulnerabilities and unintended network exposure."}, {"domain": 2, "q": "Which IAM component is a collection of IAM users managed as a single unit for assigning permissions?", "choices": ["IAM group", "IAM role", "IAM policy", "IAM identity provider"], "answer": 0, "why": "IAM groups let you attach policies to multiple users at once, simplifying permission management."}, {"domain": 2, "q": "A developer needs programmatic access to AWS resources without long-lived credentials. What should be provisioned?", "choices": ["An IAM role that the application assumes for temporary credentials", "Root user access keys", "A static IAM access key stored in the application code", "A shared IAM user password"], "answer": 0, "why": "IAM roles provide temporary, automatically rotated credentials and avoid hard-coded long-lived keys."}, {"domain": 2, "q": "Which action is a customer responsibility for data security in Amazon S3 under the shared responsibility model?", "choices": ["Maintaining the physical security of S3 data centers", "Enabling server-side encryption on S3 buckets when required", "Ensuring S3 storage devices are wiped before disposal", "Patching the S3 service software"], "answer": 1, "why": "Customers control their data and configuration choices such as enabling encryption; AWS manages infrastructure and service operation."}, {"domain": 2, "q": "What is the purpose of AWS Identity and Access Management (IAM)?", "choices": ["To monitor network traffic for threats", "To securely control access to AWS services and resources", "To encrypt data at rest in S3 automatically", "To store compliance certifications"], "answer": 1, "why": "IAM controls authentication and authorization for AWS users and resources."}, {"domain": 2, "q": "Which tool gives a consolidated view of AWS security best-practice recommendations across multiple security services?", "choices": ["AWS Security Hub", "AWS CloudTrail", "Amazon CloudWatch", "AWS Config"], "answer": 0, "why": "Security Hub consolidates security findings and checks them against security best practices and standards."}, {"domain": 2, "q": "A company wants to use its existing Microsoft Active Directory to grant employees access to the AWS Management Console. What can it use?", "choices": ["AWS IAM Identity Center with federation to the directory", "Create IAM users matching each AD account manually", "Amazon Cognito identity pools only", "AWS Directory Service with no federation capability"], "answer": 0, "why": "IAM Identity Center supports federation with external identity providers such as AD for workforce access."}, {"domain": 2, "q": "Which statement about multi-factor authentication (MFA) is correct?", "choices": ["MFA replaces the need for strong passwords", "MFA adds a second verification factor beyond a password to increase account security", "MFA is available only for the root user", "MFA encrypts data at rest automatically"], "answer": 1, "why": "MFA requires users to present two or more verification factors, greatly reducing the risk of compromised credentials."}, {"domain": 2, "q": "A company must prove to an auditor that no AWS API call has gone unnoticed. Which service provides a complete history of API calls?", "choices": ["AWS CloudTrail", "Amazon CloudWatch Logs", "AWS Config", "Amazon Inspector"], "answer": 0, "why": "CloudTrail logs account API activity, providing an auditable history of who did what and when."}, {"domain": 2, "q": "Which service automatically applies AWS security best practices at scale across a multi-account environment?", "choices": ["AWS Control Tower", "AWS Trusted Advisor", "AWS Artifact", "Amazon Macie"], "answer": 0, "why": "Control Tower uses guardrails to set up and govern a secure, compliant multi-account landing zone."}, {"domain": 2, "q": "A team needs to protect a game server from UDP flood attacks with cost protection and 24/7 DDoS response support. What should they enable?", "choices": ["AWS Shield Advanced", "AWS Shield Standard", "AWS WAF with rate limiting only", "Amazon GuardDuty"], "answer": 0, "why": "Shield Advanced provides enhanced DDoS detection, cost protection, and access to the Shield Response Team."}, {"domain": 2, "q": "Which practice helps secure an AWS account by ensuring no single user has excessive permissions?", "choices": ["Using IAM groups with least-privilege policies and regular permission reviews", "Giving every user the same policy for simplicity", "Sharing one IAM user among the team", "Using the root user for all daily operations"], "answer": 0, "why": "Groups with least-privilege policies plus periodic reviews prevent privilege accumulation."}, {"domain": 2, "q": "A company wants to assess how its current security posture compares to CIS AWS Foundations Benchmark standards. Which service should be used?", "choices": ["AWS Security Hub with the CIS standard enabled", "Amazon Macie", "AWS CloudTrail", "AWS Artifact"], "answer": 0, "why": "Security Hub can continuously check accounts against CIS AWS Foundations Benchmark controls."}, {"domain": 3, "q": "A company needs to run a web application on AWS without managing servers and only pays when requests are handled. Which service fits best?", "choices": ["Amazon EC2 On-Demand", "AWS Lambda", "Amazon RDS", "AWS Elastic Beanstalk with EC2"], "answer": 1, "why": "Lambda is serverless compute that runs code on demand and charges only for execution time."}, {"domain": 3, "q": "Which storage service is designed to store objects with any storage class automatically moving data based on access patterns to optimize cost?", "choices": ["Amazon S3 Intelligent-Tiering", "Amazon EBS gp3", "Amazon EFS Standard", "Amazon FSx for Windows"], "answer": 0, "why": "S3 Intelligent-Tiering automatically moves objects between access tiers to minimize storage costs."}, {"domain": 3, "q": "A company needs a highly available relational database with automated backups, patching, and multi-AZ failover. Which service should it use?", "choices": ["Amazon RDS", "Amazon DynamoDB", "Amazon EBS", "Amazon Redshift"], "answer": 0, "why": "RDS is a managed relational database service providing automated backups, patching, and Multi-AZ failover."}, {"domain": 3, "q": "Which service provides fully managed message queuing that decouples microservices and can retain messages up to 14 days?", "choices": ["Amazon SQS", "Amazon SNS", "Amazon EventBridge", "Amazon MQ"], "answer": 0, "why": "SQS is a managed message queue with configurable retention (default 4 days, max 14 days)."}, {"domain": 3, "q": "A company needs to connect its on-premises data center to AWS with a private, dedicated network connection. Which service should be used?", "choices": ["AWS Direct Connect", "AWS Site-to-Site VPN", "Amazon VPC peering", "AWS Transit Gateway"], "answer": 0, "why": "Direct Connect provides a dedicated private network link between on-premises and AWS."}, {"domain": 3, "q": "Which Amazon S3 storage class is most cost-effective for archiving data that is rarely accessed and can tolerate retrieval times of several hours?", "choices": ["S3 Glacier Deep Archive", "S3 Standard", "S3 Standard-IA", "S3 One Zone-IA"], "answer": 0, "why": "Glacier Deep Archive has the lowest storage cost with retrieval times typically within 12 hours."}, {"domain": 3, "q": "A company wants to run containers on AWS without managing the underlying EC2 instances. Which service should it use?", "choices": ["Amazon ECS with AWS Fargate", "Amazon EC2 Auto Scaling", "Amazon EBS", "AWS Direct Connect"], "answer": 0, "why": "Fargate is a serverless launch type for ECS/EKS that removes the need to manage servers."}, {"domain": 3, "q": "Which service distributes incoming application traffic across multiple targets such as EC2 instances in multiple Availability Zones?", "choices": ["Application Load Balancer", "Amazon Route 53", "AWS Global Accelerator only", "Amazon CloudFront"], "answer": 0, "why": "An Application Load Balancer distributes HTTP/HTTPS traffic across targets to improve availability."}, {"domain": 3, "q": "A global company wants to deliver static website content to users with low latency from locations close to them. Which service should be used?", "choices": ["Amazon CloudFront", "Amazon S3 Standard-IA only", "AWS Direct Connect", "Amazon EC2 in a single Region"], "answer": 0, "why": "CloudFront is a CDN that caches content at edge locations worldwide for low-latency delivery."}, {"domain": 3, "q": "Which service provides serverless, key-value NoSQL storage with single-digit millisecond performance at any scale?", "choices": ["Amazon DynamoDB", "Amazon RDS", "Amazon Redshift", "Amazon ElastiCache"], "answer": 0, "why": "DynamoDB is a fully managed NoSQL database designed for consistent single-digit millisecond latency."}, {"domain": 3, "q": "A company needs to send a single message to many subscribers at once, such as fan-out notifications to email, SQS, and HTTP endpoints. Which service fits?", "choices": ["Amazon SNS", "Amazon SQS", "Amazon EventBridge Scheduler", "Amazon Kinesis Data Streams"], "answer": 0, "why": "SNS is a pub/sub messaging service that fans out messages to multiple subscribers."}, {"domain": 3, "q": "Which compute option gives users full control over the operating system and instance type with per-second billing on demand?", "choices": ["Amazon EC2", "AWS Lambda", "Amazon Lightsail only", "AWS App Runner"], "answer": 0, "why": "EC2 provides resizable virtual machines with full OS control and flexible On-Demand billing."}, {"domain": 3, "q": "A company needs a block storage volume attached to an EC2 instance that behaves like a physical hard drive. Which service should be used?", "choices": ["Amazon EBS", "Amazon S3", "Amazon EFS", "AWS Storage Gateway tape"], "answer": 0, "why": "EBS provides persistent block-level storage volumes for use with EC2 instances."}, {"domain": 3, "q": "Which service provides a shared file system that can be mounted concurrently by many EC2 instances using the NFS protocol?", "choices": ["Amazon EFS", "Amazon EBS", "Amazon S3", "Amazon RDS storage"], "answer": 0, "why": "EFS is a fully managed elastic NFS file system that supports concurrent access from multiple instances."}, {"domain": 3, "q": "A data analytics team wants to query structured and semi-structured data stored in S3 using standard SQL without loading it into a database. Which service should be used?", "choices": ["Amazon Athena", "Amazon RDS for MySQL", "Amazon Redshift only with data loaded", "Amazon DynamoDB"], "answer": 0, "why": "Athena is a serverless query service that runs SQL directly against data in S3."}, {"domain": 3, "q": "A company needs to run a batch image-processing job that can tolerate interruptions and wants the lowest possible compute cost. Which purchasing option should the company use?", "choices": ["On-Demand Instances", "Reserved Instances", "Spot Instances", "Dedicated Hosts"], "answer": 2, "why": "Spot Instances offer the steepest discounts for fault-tolerant, interruptible workloads."}, {"domain": 3, "q": "A company wants to move its on-premises Oracle database to AWS without changing the database engine. Which service should the company use?", "choices": ["AWS Database Migration Service with the homogenous migration option", "AWS Schema Conversion Tool only", "Amazon ElastiCache", "AWS Glue"], "answer": 0, "why": "DMS supports homogenous migrations, keeping the same engine while moving data to RDS or EC2."}, {"domain": 3, "q": "A company needs to transfer 50 TB of on-premises data to Amazon S3 and has a slow network connection. Which solution meets this requirement?", "choices": ["AWS Snowball Edge device", "Amazon Kinesis Data Streams", "AWS Transfer Family", "AWS DataSync over the internet only"], "answer": 0, "why": "Snowball Edge physically ships large datasets, avoiding slow or unreliable network transfer."}, {"domain": 3, "q": "A company wants to track all resource changes in its AWS accounts, including who made a change and when. Which service provides this capability?", "choices": ["AWS CloudTrail", "AWS Config", "Amazon CloudWatch Logs", "AWS Trusted Advisor"], "answer": 0, "why": "CloudTrail records API activity, capturing who made changes and when."}, {"domain": 3, "q": "A company wants to use a prebuilt workflow to set up a multi-account environment with best-practice guardrails. Which service should the company use?", "choices": ["AWS Control Tower", "AWS Organizations", "AWS Service Catalog", "AWS Systems Manager"], "answer": 0, "why": "Control Tower automates landing zone setup with guardrails across AWS accounts."}, {"domain": 3, "q": "Which service enables a company to run containerized applications without managing servers or clusters?", "choices": ["Amazon ECS on Amazon EC2", "Amazon EKS with self-managed worker nodes", "Amazon ECR", "Amazon ECS on AWS Fargate"], "answer": 3, "why": "Fargate is a serverless compute engine for containers, removing server and cluster management."}, {"domain": 3, "q": "A company needs to send emails, SMS messages, and push notifications to millions of users. Which service should the company use?", "choices": ["Amazon SQS", "Amazon SNS", "Amazon SES", "Amazon EventBridge"], "answer": 1, "why": "SNS is a pub/sub service that fans out messages to email, SMS, and mobile push endpoints."}, {"domain": 3, "q": "A company runs an application on Amazon EC2 and needs to automatically add instances when CPU utilization rises above 70%. Which feature should the company use?", "choices": ["Amazon EC2 Auto Scaling", "AWS Elastic Beanstalk health monitoring", "Elastic Load Balancing", "AWS Systems Manager State Manager"], "answer": 0, "why": "EC2 Auto Scaling policies automatically add or remove instances based on demand."}, {"domain": 3, "q": "Which AWS service or feature provides a private, dedicated network connection between an on-premises data center and AWS?", "choices": ["AWS VPN", "AWS Direct Connect", "Amazon VPC peering", "AWS Transit Gateway"], "answer": 1, "why": "Direct Connect provides a dedicated private network link to AWS with consistent bandwidth and latency."}, {"domain": 3, "q": "A company needs a highly available DNS service to route user traffic to the closest healthy AWS Region. Which service should the company use?", "choices": ["Amazon CloudFront", "Amazon Route 53", "Elastic Load Balancing", "AWS Global Accelerator"], "answer": 1, "why": "Route 53 is a managed DNS service with routing policies such as latency and geolocation routing."}, {"domain": 3, "q": "A company wants to deploy a web application without thinking about provisioning or operating servers. Which service BEST meets this requirement?", "choices": ["Amazon EC2", "AWS Lambda", "Amazon EKS", "AWS Snowball"], "answer": 1, "why": "Lambda is a serverless compute service that runs code without server provisioning or management."}, {"domain": 3, "q": "Which storage option provides a file system that can be mounted concurrently by thousands of Amazon EC2 instances?", "choices": ["Amazon EBS", "Amazon S3", "Amazon EFS", "AWS Storage Gateway tape gateway"], "answer": 2, "why": "EFS is a shared elastic file system that scales automatically and supports concurrent NFS mounts."}, {"domain": 3, "q": "A company needs to store backup data on AWS for 10 years, with retrieval required only rarely. Which storage class offers the LOWEST cost?", "choices": ["S3 Standard", "S3 Glacier Deep Archive", "S3 One Zone-IA", "S3 Standard-IA"], "answer": 1, "why": "S3 Glacier Deep Archive is the lowest-cost storage class for long-term archival data."}, {"domain": 3, "q": "Which service should a company use to run managed PostgreSQL and MySQL databases in the cloud?", "choices": ["Amazon DynamoDB", "Amazon RDS", "Amazon Redshift", "Amazon DocumentDB"], "answer": 1, "why": "Amazon RDS is a managed relational database service supporting PostgreSQL and MySQL."}, {"domain": 3, "q": "A company needs to process streaming data from IoT devices in real time before storing it. Which service should the company use?", "choices": ["Amazon S3", "Amazon Kinesis Data Streams", "AWS Step Functions", "Amazon CloudWatch"], "answer": 1, "why": "Kinesis Data Streams ingests and processes high-volume streaming data in real time."}, {"domain": 3, "q": "Which task is a responsibility of AWS under the AWS shared responsibility model?", "choices": ["Configuring security groups", "Patching the hypervisor on which EC2 instances run", "Managing guest operating system updates", "Encrypting application data"], "answer": 1, "why": "AWS is responsible for the physical infrastructure and the underlying hypervisor."}, {"domain": 3, "q": "A company wants to run a self-managed Kubernetes cluster with full control over the control plane configuration. Which service should the company use?", "choices": ["Amazon ECS on Fargate", "Amazon EC2 with Kubernetes installed", "AWS Lambda with containers", "AWS Batch"], "answer": 1, "why": "Self-managed Kubernetes on EC2 gives full control; EKS is the managed alternative."}, {"domain": 3, "q": "Which service decouples application components by allowing producers and consumers to communicate asynchronously through queues?", "choices": ["Amazon SNS", "Amazon SQS", "Amazon Kinesis Data Analytics", "Amazon MQ only for MQTT"], "answer": 1, "why": "SQS is a managed message queue service that decouples and scales application components."}, {"domain": 3, "q": "A company needs to distribute incoming application traffic across multiple EC2 instances in multiple Availability Zones. Which service should the company use?", "choices": ["AWS Global Accelerator", "Amazon Route 53", "Elastic Load Balancing", "Amazon CloudFront"], "answer": 2, "why": "ELB automatically distributes traffic across targets in multiple Availability Zones."}, {"domain": 3, "q": "A company wants to store commonly accessed data with milliseconds-level latency but reduce costs by moving infrequently accessed data automatically. Which service should the company use?", "choices": ["Amazon RDS storage autoscaling", "Amazon S3 Intelligent-Tiering", "Amazon EBS gp3 volumes", "AWS Backup"], "answer": 1, "why": "S3 Intelligent-Tiering moves objects between access tiers automatically to optimize cost."}, {"domain": 3, "q": "A company is migrating a large on-premises VMware environment to AWS and wants to move virtual machines with minimal changes. Which tool should the company use?", "choices": ["AWS Application Migration Service", "AWS Snowball", "AWS Transfer Family", "AWS Control Tower"], "answer": 0, "why": "Application Migration Service automates lift-and-shift replication of on-premises servers, including VMware, to AWS."}, {"domain": 4, "q": "Which tool should a company use to receive a detailed report that itemizes AWS usage and costs by account and tag?", "choices": ["AWS Cost Explorer", "AWS Budgets", "AWS Cost and Usage Report (CUR)", "AWS Pricing Calculator"], "answer": 2, "why": "CUR delivers the most detailed usage and cost data file, itemized by account, service, and tag."}, {"domain": 4, "q": "A company wants to estimate the monthly cost of a new AWS architecture BEFORE deploying it. Which tool should the company use?", "choices": ["AWS Cost Explorer", "AWS Pricing Calculator", "AWS Budgets", "AWS Cost and Usage Report"], "answer": 1, "why": "The Pricing Calculator estimates costs for architectures before deployment."}, {"domain": 4, "q": "Which pricing model offers the largest discount in exchange for a 1-year or 3-year commitment to consistent usage?", "choices": ["Savings Plans", "Spot Instances", "On-Demand", "Pay-as-you-go"], "answer": 0, "why": "Savings Plans offer the largest discounts for committed consistent usage over 1 or 3 years."}, {"domain": 4, "q": "A data transfer occurs OUTBOUND from an AWS Region to the internet. How is this data transfer charged?", "choices": ["Free of charge", "Charged per GB after the free tier allowance", "Charged only if encrypted", "Charged at the same rate regardless of direction"], "answer": 1, "why": "Outbound (egress) data transfer to the internet is charged per GB after the free tier; inbound is free."}, {"domain": 4, "q": "A company wants to receive alerts when its AWS spending approaches a defined threshold. Which service should the company use?", "choices": ["AWS Cost Explorer", "AWS Budgets", "AWS Trusted Advisor", "AWS Cost and Usage Report"], "answer": 1, "why": "AWS Budgets sends alerts when actual or forecasted costs exceed defined thresholds."}, {"domain": 4, "q": "A company wants to allocate its AWS costs to internal departments by using a consistent tagging strategy. Which feature should the company use?", "choices": ["AWS Config rules", "Cost allocation tags", "Amazon Inspector findings", "AWS Resource Access Manager"], "answer": 1, "why": "Cost allocation tags enable grouping and allocating costs in billing reports by tag."}, {"domain": 4, "q": "Which AWS Support plan provides access to a Technical Account Manager (TAM)?", "choices": ["Basic", "Developer", "Business", "Enterprise"], "answer": 3, "why": "Only the Enterprise support plan includes a dedicated Technical Account Manager."}, {"domain": 4, "q": "Which support plan provides 24x7 access to customer service and access to documentation, whitepapers, and forums at no charge?", "choices": ["Basic", "Developer", "Business", "Enterprise"], "answer": 0, "why": "The Basic plan is free and includes customer service, documentation, and forums."}, {"domain": 4, "q": "A company wants to compare the cost of running its workload on-premises versus on AWS. Which tool should the company use?", "choices": ["AWS TCO calculator", "AWS Pricing Calculator", "AWS Cost Explorer", "AWS Budgets"], "answer": 0, "why": "The TCO calculator compares on-premises and AWS costs over time, including hardware and operations."}, {"domain": 4, "q": "Which statement about the AWS Free Tier is accurate?", "choices": ["The 12-month free tier applies to some services after account creation", "All AWS services are free for 12 months", "The free tier applies only to the Enterprise support plan", "Free tier usage is unlimited for S3 storage"], "answer": 0, "why": "Many services offer 12-month free tier allowances from account creation, with service-specific limits."}, {"domain": 4, "q": "Which AWS Trusted Advisor check helps identify idle load balancers and unattached EBS volumes?", "choices": ["Security groups check", "Cost optimization checks", "Fault tolerance checks", "Performance checks"], "answer": 1, "why": "Trusted Advisor cost optimization checks flag idle resources such as unattached volumes and idle load balancers."}, {"domain": 4, "q": "Under consolidated billing in AWS Organizations, how are EC2 Reserved Instances treated across accounts?", "choices": ["Discounts apply only to the account that purchased them", "Unused RI discounts are shared with other accounts in the organization", "RIs must be repurchased per account", "RIs are converted to Savings Plans automatically"], "answer": 1, "why": "Consolidated billing shares unused RI and Savings Plan discounts across member accounts."}, {"domain": 4, "q": "A company can tolerate interruptions for a nightly batch job but needs steady compute capacity for its production database at a predictable cost for 3 years. Which combination of purchasing options should the company use?", "choices": ["Spot for the database and On-Demand for the batch job", "Reserved Instances for the database and Spot for the batch job", "On-Demand for both workloads", "Dedicated Hosts for both workloads"], "answer": 1, "why": "Reserved Instances fit steady-state predictable workloads, and Spot fits interruptible batch workloads."}, {"domain": 4, "q": "Which action helps a company estimate costs BEFORE running compute workloads by selecting an instance type and pricing model?", "choices": ["Using AWS Pricing Calculator for EC2", "Generating a CUR report", "Enabling cost allocation tags", "Creating a billing alarm in CloudWatch"], "answer": 0, "why": "The Pricing Calculator estimates EC2 costs by instance type, region, and pricing model before deployment."}, {"domain": 4, "q": "A company wants to visualize its AWS spending trends over the past 12 months and forecast future costs. Which tool should the company use?", "choices": ["AWS Pricing Calculator", "AWS Cost Explorer", "AWS Budgets", "AWS Organizations"], "answer": 1, "why": "Cost Explorer visualizes historical spend and forecasts future costs."}, {"domain": 4, "q": "Which statement describes the AWS pay-as-you-go pricing model?", "choices": ["Costs are fixed regardless of usage", "You pay only for the resources you use with no upfront costs or long-term contracts", "Payment is required one year in advance", "Pricing varies by the number of AWS accounts"], "answer": 1, "why": "Pay-as-you-go charges only for consumed resources with no upfront commitments."}, {"domain": 4, "q": "A company needs a phone-accessible support engineer available 24x7 with response times of 15 minutes for business-critical system-down issues. Which support plan should the company choose at MINIMUM?", "choices": ["Basic", "Developer", "Business", "Enterprise"], "answer": 2, "why": "The Business plan provides 24x7 phone support and 15-minute response for system-down cases."}, {"domain": 4, "q": "A company wants to group its AWS accounts by business unit and receive a single bill with volume pricing discounts. Which service should the company use?", "choices": ["AWS Control Tower", "AWS Organizations consolidated billing", "AWS Resource Access Manager", "AWS Service Catalog"], "answer": 1, "why": "Organizations consolidated billing combines accounts into one bill and can unlock volume discounts."}, {"domain": 4, "q": "Which task is the customer's responsibility under the shared responsibility model for pricing and security?", "choices": ["Patching the RDS database engine", "Encrypting data at rest in an S3 bucket", "Maintaining the physical security of data centers", "Replacing failed hardware"], "answer": 1, "why": "Customers are responsible for encrypting their own data; AWS handles engine patching, hardware, and facilities."}, {"domain": 4, "q": "A company's monthly AWS bill spiked unexpectedly, and the company wants to identify which service and Region caused the increase. Which tool provides this detail?", "choices": ["AWS Cost Explorer with service and Region filters", "AWS Pricing Calculator", "AWS Support Basic plan reports", "AWS Trusted Advisor performance checks"], "answer": 0, "why": "Cost Explorer filters and groups costs by service, Region, account, and tag to find cost drivers."}, {"domain": 4, "q": "Which pricing factor applies to both Amazon S3 and Amazon EBS?", "choices": ["Number of API requests only", "Storage capacity used per month", "Data transfer OUTBOUND to the internet only", "Number of instances"], "answer": 1, "why": "Both S3 and EBS charge primarily based on the amount of storage provisioned or used per month."}, {"domain": 4, "q": "A company wants to use cost allocation tags but has existing resources without tags. What should the company do to apply tags to the existing resources?", "choices": ["Wait for AWS to auto-tag them", "Use AWS Resource Groups and Tag Editor or the Tag Editor console to tag existing resources", "Terminate and relaunch all resources", "Enable them in the CUR only"], "answer": 1, "why": "The Tag Editor and Resource Groups tool bulk-tag existing resources across accounts and Regions."}, {"domain": 4, "q": "What is a key benefit of moving to the AWS Cloud from a TCO perspective?", "choices": ["Eliminating all operational staff", "Replacing large upfront capital expenditures with pay-as-you-go operational costs", "Guaranteeing lower costs in every scenario", "Removing the need for any capacity planning"], "answer": 1, "why": "Cloud TCO benefit comes from converting CapEx to variable OpEx paid as resources are used."}, {"domain": 4, "q": "A company wants to review its AWS bill for a specific month and download the full statement as a PDF. Which tool should the company use?", "choices": ["AWS Pricing Calculator", "AWS Bills page in the console", "AWS Trusted Advisor", "AWS Cost and Usage Report only"], "answer": 1, "why": "The Bills page in the console shows month-by-month charges and can be downloaded as a PDF statement."}];
